if (enable) {
    imsic_csr_write(IMSIC_EITHRESHOLD, IMSIC_ENABLE_EITHRESHOLD);
    imsic_csr_write(IMSIC_EIDELIVERY, IMSIC_ENABLE_EIDELIVERY);
    return;
}
imsic_csr_write(IMSIC_EIDELIVERY, IMSIC_DISABLE_EIDELIVERY);
imsic_csr_write(IMSIC_EITHRESHOLD, IMSIC_DISABLE_EITHRESHOLD);

imsic_vs_csr_write(IMSIC_EITHRESHOLD, mrif->eithreshold);
imsic_vs_csr_write(IMSIC_EIDELIVERY, mrif->eidelivery);
csr_write(CSR_HSTATUS, old_hstatus);
csr_write(CSR_VSISELECT, old_vsiselect);

if (imsic_mrif_atomic_read(mrif, &mrif->eidelivery) &&
    imsic_mrif_topei(mrif, imsic->nr_eix, imsic->nr_msis))
    kvm_riscv_vcpu_set_interrupt(vcpu, IRQ_VS_EXT);
else
    kvm_riscv_vcpu_unset_interrupt(vcpu, IRQ_VS_EXT);

if (!riscv_isa_extension_available(NULL, SxAIA)) {
    pr_err("%pfwP: AIA support not available\n", fwnode);
    return -ENODEV;
}

raw_spin_lock_irqsave(&lpriv->lock, flags);
if (force_all)
    bitmap_fill(lpriv->dirty_bitmap, imsic->global.nr_ids + 1);
if (!__imsic_local_sync(lpriv))
    __imsic_local_timer_start(lpriv, smp_processor_id());
raw_spin_unlock_irqrestore(&lpriv->lock, flags);

case IMSIC_EIDELIVERY:
    old_val = imsic_mrif_atomic_rmw(mrif, &mrif->eidelivery, new_val, wr_mask & 0x1);
    break;
case IMSIC_EITHRESHOLD:
    old_val = imsic_mrif_atomic_rmw(mrif, &mrif->eithreshold, new_val, wr_mask & (IMSIC_MAX_ID - 1));
    break;
